INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2601, 'Exodus 39:13', 'Exodus', 39, 13, '&nbsp;او په څلورم قطار کښې يو ايکوامرين، يو اونيکس کاڼے او يو جاسپر کاڼے ولګولو. دا په سرو زرو کښې ګېر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2602, 'Exodus 39:14', 'Exodus', 39, 14, '&nbsp;په دې دولسو کاڼو په هر يو کاڼى باندې د يعقوب د يو زوئ نوم ليکلے وو، چې د بنى اِسرائيلو د دولسو قبيلو نمائندګى وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2603, 'Exodus 39:15', 'Exodus', 39, 15, '&nbsp;د سينې جېب دپاره هغوئ د سوچه سرو زرو زنځيرونه جوړ کړل، چې د تارونو په شان تاو شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2604, 'Exodus 39:16', 'Exodus', 39, 16, '&nbsp;هغوئ د کاڼو ګېرولو دپاره د سرو زرو دوه څيزونه جوړ کړل او د سرو زرو دوه کَړۍ او دا دوه کَړۍ يې د سينې جېب په بره ګوټونو پورې ونښلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2605, 'Exodus 39:17', 'Exodus', 39, 17, '&nbsp;هغوئ د سرو زرو هغه دوه زنځيرونه په دوه کَړو پورې يې وتړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2606, 'Exodus 39:18', 'Exodus', 39, 18, '&nbsp;او د زنځيرونو نور دوه سرونه يې په هغه دوه څيزونو پورې وتړل چې په هغې کښې کاڼى ګېر کړے شوى وُو او داسې يې دا د پېش بند د ولى په پټو پورې مخکښې ونښلول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2607, 'Exodus 39:19', 'Exodus', 39, 19, '&nbsp;هغوئ دوه د سرو زرو کَړۍ جوړې کړې او دا يې د سينې جېب لاندې ګوټونو دننه غاړې ته د پېش بند خوا کښې ونښلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2608, 'Exodus 39:20', 'Exodus', 39, 20, '&nbsp;هغوئ د سرو زرو دوه نورې کَړۍ هم جوړې کړې او دا يې په لاندې حِصه پورې د پېش بند د ولى دوه پټو په مخکښې ونښلولې چې ګنډ ته نزدې وې او په ګُلکارۍ ښائسته کړے شوى کمربند دپاسه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2609, 'Exodus 39:21', 'Exodus', 39, 21, '&nbsp;هم هغه شان چې څنګه مالِک خُدائ موسىٰ ته حُکم ورکړے وو، هغوئ د سينې د جېب کَړۍ د پېش بند کَړو پورې د آسمانى رنګ مزى سره وتړلې، نو چې داسې د سينې جېب په کمربند باندې پروت وى او چې ترې نه لرې کيږى نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2610, 'Exodus 39:22', 'Exodus', 39, 22, '&nbsp;چې کومه چُوغه د پېش بند لاندې اغوستلے کيږى هغه ټوله د آسمانى رنګ وړۍ نه جوړه شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2611, 'Exodus 39:23', 'Exodus', 39, 23, '&nbsp;په هغې کښې د سر دپاره يو سورے وو، چې غاړه يې مضبوطه ګنډلے شوې وه چې ونۀ شليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2612, 'Exodus 39:27', 'Exodus', 39, 27, '&nbsp;هغوئ د هارون او د هغۀ د زامنو دپاره قميصونه جوړ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2613, 'Exodus 39:28', 'Exodus', 39, 28, '&nbsp;او پټکے، ټوپۍ او د کتان جانګى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2614, 'Exodus 39:29', 'Exodus', 39, 29, '&nbsp;او د کتان او د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه يې کمربند جوړ کړو چې ګُلکارى ورباندې شوې وه، هم هغه شان لکه چې څنګه مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2615, 'Exodus 39:30', 'Exodus', 39, 30, '&nbsp;هغوئ د سوچه سرو زرو نه نښه جوړه کړه او په دې باندې يې وليکل ”مالِک خُدائ ته وقف شوے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2616, 'Exodus 39:31', 'Exodus', 39, 31, '&nbsp;هغوئ دا د يو آسمانى رنګ مزى سره د پټکى مخې ته وتړله، هم هغه شان څنګه چې مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2617, 'Exodus 39:32', 'Exodus', 39, 32, '&nbsp;د مالِک خُدائ د حضور خېمې ټول کار په ښۀ توګه سر ته ورسېدو. بنى اِسرائيلو هر څۀ هم هغه شان وکړل چې څنګه مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2618, 'Exodus 39:33', 'Exodus', 39, 33, '&nbsp;هغوئ خېمه او د هغې ټول سامان موسىٰ له راوړو، د دې کُنډې، چوکاټونه، لاړى، ستنې او د دې پښې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2619, 'Exodus 39:34', 'Exodus', 39, 34, '&nbsp;د ګډو څرمنې نه جوړه شوې پړده چې سور رنګ ورکړے شوے وو، د ښې څرمنې نه جوړه پړده، د پټولو والا پړده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2620, 'Exodus 39:35', 'Exodus', 39, 35, '&nbsp;د لوظ صندوق چې د کاڼو تختې په کښې پرتې وې، د دې د وړلو دپاره بازوګان او د دې د کفارې تخت هم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2621, 'Exodus 39:36', 'Exodus', 39, 36, '&nbsp;مېز او د دې ټول سامان او خُدائ پاک ته پېش کړے شوې روټۍ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2622, 'Exodus 39:37', 'Exodus', 39, 37, '&nbsp;د سوچه سرو زرو ډيوټ، د دې ډيوې او د دې ټول سامان او د ډيوو دپاره تېل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2623, 'Exodus 39:38', 'Exodus', 39, 38, '&nbsp;د سرو زرو قربان‌ګاه، د غوړولو تېل، د خوشبويۍ مصالحې، خېمې ته د ننوتلو دروازې دپاره پړده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2624, 'Exodus 39:39', 'Exodus', 39, 39, '&nbsp;د زېړو قربان‌ګاه او ورسره د دې د زېړو جالۍ، د دې د وړلو دپاره بازوګان او د دې ټول سامان، د وينځلو دپاره ښانک او د دې بېخ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2625, 'Exodus 39:40', 'Exodus', 39, 40, '&nbsp;د دربار دپاره پړدې او د دې ستنې او پښې، دربار ته د ننوتلو دپاره پړده او د دې رسۍ، د خېمې دپاره موږى، او هغه ټول سامان چې په خېمه کښې استعمالېدلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2626, 'Exodus 39:41', 'Exodus', 39, 41, '&nbsp;او د اِمامانو ښائسته لِباس چې په مقدس ځائ کښې د خِدمت په وخت اغوستلے شو. د هارون او د هغۀ د زامنو دپاره مقدس لِباس وو چې کله هغوئ د اِمامانو په توګه خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2627, 'Exodus 39:42', 'Exodus', 39, 42, '&nbsp;بنى اِسرائيلو ټول کار هم هغه شان سر ته رسولے وو چې څنګه مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2628, 'Exodus 39:43', 'Exodus', 39, 43, '&nbsp;موسىٰ هغه ټول کار ته وکتل او وې ليدل چې هغوئ دا په صحيح توګه هم هغه شان کړے وو څنګه چې مالِک خُدائ حُکم کړے وو. نو موسىٰ د هغوئ دپاره برکت وغوښتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2629, 'Exodus 40:1', 'Exodus', 40, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2630, 'Exodus 40:2', 'Exodus', 40, 2, '&nbsp;”د اولنۍ مياشتې په اوله ورځ مالِک خُدائ د حضور خېمه ودروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2631, 'Exodus 40:3', 'Exodus', 40, 3, '&nbsp;په دې کښې د لوظ صندوق کېږده په کوم کښې چې لس حُکمونه دى او د دې په مخکښې پړده ولګوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2632, 'Exodus 40:4', 'Exodus', 40, 4, '&nbsp;هغه مېز دننه راوړه او سامان ورباندې کېږده. ډيوټ هم دننه راوړه او ډيوې ورباندې کېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2633, 'Exodus 40:5', 'Exodus', 40, 5, '&nbsp;د لوظ صندوق په مخکښې د سرو زرو قربان‌ګاه کېږده کومه چې د سوزېدونکې خوشبويۍ دپاره ده او د خېمې په دروازه باندې پړده ځوړنده کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2634, 'Exodus 40:6', 'Exodus', 40, 6, '&nbsp;د خېمې په مخکښې د سوزېدونکې نذرانې قربان‌ګاه کېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2635, 'Exodus 40:7', 'Exodus', 40, 7, '&nbsp;د خېمې او قربان‌ګاه په مينځ کښې د وينځلو ښانک کېږده او اوبۀ په کښې واچوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2636, 'Exodus 40:8', 'Exodus', 40, 8, '&nbsp;ګېرچاپېره پړدې ودروه او د دې په دروازه باندې پړده ځوړنده کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2637, 'Exodus 40:9', 'Exodus', 40, 9, '&nbsp;بيا د زيتُونو په تېلو باندې غوړولو سره خېمه او د دې ټول سامان وقف کړه او داسې به دا مقدس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2638, 'Exodus 40:10', 'Exodus', 40, 10, '&nbsp;ورپسې، د غوړولو د تېلو په ذريعه د سوزېدونکې نذرانې قربان‌ګاه او د دې ټول سامان وقف کړه او قربان‌ګاه به پوره مقدسه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2639, 'Exodus 40:11', 'Exodus', 40, 11, '&nbsp;د وينځلو ښانک او د دې بېخ هم په داسې طريقه وقف کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2640, 'Exodus 40:12', 'Exodus', 40, 12, '&nbsp;هارون او د هغۀ زامن د خېمې دروازې ته راوله او هغوئ ته ووايه چې غسل وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2641, 'Exodus 40:13', 'Exodus', 40, 13, '&nbsp;هارون ته مقدسې جامې ورواغونده، سر يې په تېلو غوړ کړه او وقف يې کړه، نو هغه به د اِمام په توګه زما خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2642, 'Exodus 40:14', 'Exodus', 40, 14, '&nbsp;د هغۀ زامن راوله او هغوئ ته چُوغې ورواغونده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2643, 'Exodus 40:15', 'Exodus', 40, 15, '&nbsp;بيا د هغوئ سر په تېلو غوړ کړه، هم هغه شان چې څنګه دې د هغوئ د پلار سر غوړ کړے وو، نو چې د اِمامانو په توګه زما خِدمت وکړى. دا غوړول به هغوئ د راتلونکى ټولو وختونو دپاره اِمامان جوړ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2644, 'Exodus 40:16', 'Exodus', 40, 16, '&nbsp;موسىٰ هر څۀ هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2645, 'Exodus 40:17', 'Exodus', 40, 17, '&nbsp;چې کله هغوئ د مِصر نه راووتل نو د دوېم کال د اولنۍ مياشتې اوله ورځ وه چې د مالِک خُدائ د حضور خېمه ودرولے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2646, 'Exodus 40:18', 'Exodus', 40, 18, '&nbsp;موسىٰ د دې پښې لاندې ولګولې، چوکاټونه يې ودرول، لاړى يې ورسره ولګول او د دې ستنې يې ودرولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2647, 'Exodus 40:19', 'Exodus', 40, 19, '&nbsp;هغۀ په خېمه باندې د پټولو دپاره پړده خوره کړه او دپاسه يې پرې بله پړده هم واچوله، لکه څنګه چې مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2648, 'Exodus 40:20', 'Exodus', 40, 20, '&nbsp;بيا هغۀ د کاڼو دوه تختې واخستلې او د لوظ صندوق کښې يې کېښودلې. هغۀ د صندوق په کَړو کښې بازوګان واچول او د دې د کفارې تخت يې پرې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2649, 'Exodus 40:21', 'Exodus', 40, 21, '&nbsp;بيا هغۀ صندوق خېمې ته دننه راوړو او پړده يې ځوړنده کړه. نو داسې هغۀ صندوق پټ کړو، هم هغه شان چې څنګه مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2650, 'Exodus 40:22', 'Exodus', 40, 22, '&nbsp;د پړدې نه بهر شمالى طرف ته يې په خېمه کښې مېز کېښودو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2651, 'Exodus 40:23', 'Exodus', 40, 23, '&nbsp;او په دې باندې يې مالِک خُدائ ته پېش کړے شوې روټۍ کېښوده، هم هغه شان چې څنګه مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2652, 'Exodus 40:24', 'Exodus', 40, 24, '&nbsp;مېز ته مخامخ، جنوب طرف ته، هغۀ په خېمه کښې ډيوټ کېښودو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2653, 'Exodus 40:25', 'Exodus', 40, 25, '&nbsp;او هغۀ هلته د مالِک خُدائ په حضور کښې ډيوې بلې کړې، هم هغه شان چې څنګه مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2654, 'Exodus 40:26', 'Exodus', 40, 26, '&nbsp;پړدې ته مخامخ، هغۀ په خېمه کښې د سرو زرو قربان‌ګاه کېښوده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
